import{_ as a,a0 as l,w as u,s as p,ao as r,I as s,x as n,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"黑客们成功地在土豆上安装了 Linux ！ | LCTT x X-CMD","titleTemplate":false,"description":"黑客们成功地在土豆上安装了 Linux ！ | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"黑客们成功地在土豆上安装了 Linux ！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"黑客们成功地在土豆上安装了 Linux ！ | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151107 Hackers Successfully Install Linux on a Potato","title":"黑客们成功地在土豆上安装了 Linux ！","tag":"201601","desc":""},"relativePath":"201601/20151107 Hackers Successfully Install Linux on a Potato.md","filePath":"[post].md"}'),x={name:"201601/20151107 Hackers Successfully Install Linux on a Potato.md"};function L(m,t,d,f,T,b){const o=l("Link");return u(),p("div",null,[t[15]||(t[15]=r('<h1 id="黑客们成功地在土豆上安装了-linux" tabindex="-1">黑客们成功地在土豆上安装了 Linux ！ <a class="header-anchor" href="#黑客们成功地在土豆上安装了-linux" aria-label="Permalink to “黑客们成功地在土豆上安装了 Linux ！”">​</a></h1><p>来自荷兰阿姆斯特丹的消息称，LinuxOnAnything.nl 网站的黑客们成功地在土豆上安装了 Linux！这是该操作系统第一次在根用蔬菜（root vegetable）上安装成功（LCTT 译注：root vetetable，一语双关，root 在 Linux 是指超级用户）。</p><p><img src="http://www.bbspot.com/Images/News_Features/2008/12/linux-potato.jpg" alt="Linux Potato"></p><p>“土豆没有 CPU，内存和存储器，这真的是个挑战，” Linux On Anything (LOA) 小组的 Johan Piest 说。“显然我们不能使用一个像 Fedora 或 Ubuntu 这些体量较大的发行版，所以我们用的是 Damn Small Linux。”</p><p>在尝试了几周之后，LOA 小组的的同学们弄出了一个适合土豆的 Linux 内核，这玩艺儿上面可以用 vi 来编辑小的文本文件。这个 Linux 通过一个小型的 U 盘加载到土豆上，并通过一组红黑线以二进制的方式向这个土豆发送命令。</p><p>LOA 小组是一个不断壮大的黑客组织的分支；这个组织致力于将 Linux 安装到所有物体上；他们先是将 Linux 装到Gameboy 和 iPod 等电子产品上，不过最近他们在挑战一些高难度的东西，譬如将Linux安装到灯泡和小狗身上！</p><p>LOA 小组在与另一个黑客小组 Stuttering Monarchs 竞赛，看谁先拿到土豆这一分。“土豆是一种每个人都会接触到的蔬菜，它的用途就像 Linux 一样极其广泛。无论你是想煮捣烹炸还是别的都可以” Piest 说道，“你也许认为我们完成这个挑战是为了获得某些好处，而我们只是追求逼格而已。”</p><p>LOA 是第一个将 Linux 安装到一匹设德兰矮种马上的小组，但这五年来竞争愈演愈烈，其它黑客小组的进度已经反超了他们。</p><p>“我们本来可以成为在饼干上面安装 Linux 的第一个小组，但是那群来自挪威的混蛋把我们击败了。” Piest 说。</p><p>第一个成功安装了 Linux 的蔬菜是一头卷心菜，它是由一个土耳其的一个黑客小组完成的。</p><p>（好啦——是不是已经目瞪口呆，事实上，这是一篇好几年前的恶搞文，你看出来了吗？哈哈哈哈）</p><hr>',12)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),e(o,{href:"http://www.bbspot.com/news/2008/12/linux-on-a-potato.html"},{default:i(()=>[...t[0]||(t[0]=[n("http://www.bbspot.com/news/2008/12/linux-on-a-potato.html",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=n("作者：",-1)),e(o,{href:"briggsb@bbspot.com"},{default:i(()=>[...t[2]||(t[2]=[n("Brian Briggs",-1)])]),_:1}),t[7]||(t[7]=n(" 译者：",-1)),e(o,{href:"https://github.com/StdioA"},{default:i(()=>[...t[3]||(t[3]=[n("StdioA",-1)])]),_:1}),t[8]||(t[8]=n(", ",-1)),e(o,{href:"https://github.com/hittlle"},{default:i(()=>[...t[4]||(t[4]=[n("hittlle",-1)])]),_:1}),t[9]||(t[9]=n(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[5]||(t[5]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=n("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[n("LCTT",-1)])]),_:1}),t[13]||(t[13]=n(" 原创编译，",-1)),e(o,{href:"https://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[n("Linux中国",-1)])]),_:1}),t[14]||(t[14]=n(" 荣誉推出",-1))])])}const P=a(x,[["render",L]]);export{w as __pageData,P as default};
